-- Make every handbook direction available to the quote/sample workflow too.
INSERT INTO creative_product_template (
    template_code, selection_option_id, product_name, product_type, material, process,
    specification, sample_moq, bulk_moq, sample_fee_yuan, indicative_retail_display,
    sample_lead_time, bulk_lead_time, supply_status, fulfillment_mode, copyright_requirement,
    published, sort_order
)
SELECT
    CONCAT('manual-', o.option_key), o.id, o.name, o.category_key, o.material, o.process,
    o.specification, 1, 50, NULL, o.retail_display, o.sample_lead_time, o.bulk_lead_time,
    'pending_confirmation', 'preorder',
    '用户须确认拥有原创权、合法授权或公共领域依据；食品、贵金属、品牌联名和博物馆 IP 另需资质与授权核验。',
    1, o.sort_order
FROM selection_option o
WHERE o.option_key LIKE 'manual-%'
ON DUPLICATE KEY UPDATE
    selection_option_id=VALUES(selection_option_id), product_name=VALUES(product_name),
    product_type=VALUES(product_type), material=VALUES(material), process=VALUES(process),
    specification=VALUES(specification), indicative_retail_display=VALUES(indicative_retail_display),
    sample_lead_time=VALUES(sample_lead_time), bulk_lead_time=VALUES(bulk_lead_time),
    copyright_requirement=VALUES(copyright_requirement), published=VALUES(published),
    sort_order=VALUES(sort_order), updated_at=CURRENT_TIMESTAMP;
